package com.arix.player;
import android.os.*;import android.content.*;import android.widget.*;
public class HomeActivity extends BaseActivity {public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=page("Arix Player");l.addView(text("الصق رابط الفيديو لتشغيله",16,0xffc4c6cb,false));EditText u=input("https://…");l.addView(u);Button p=button("تشغيل الفيديو");l.addView(p);p.setOnClickListener(v->play(u.getText().toString()));Button i=button("معلومات التطبيق");l.addView(i);i.setOnClickListener(v->startActivity(new Intent(this,InformationActivity.class)));Button s=button("مشاركة التطبيق");l.addView(s);s.setOnClickListener(v->{Intent x=new Intent(Intent.ACTION_SEND);x.setType("text/plain");x.putExtra(Intent.EXTRA_TEXT,"Arix Player");startActivity(Intent.createChooser(x,"مشاركة"));});if(getIntent().getData()!=null)u.setText(getIntent().getData().toString());}}
